INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l10','be made in','',NULL,'/bi meɪd ɪn/','It was made in Germany.','它是德国制造的。','This watch was made in Switzerland.','这块表是瑞士产的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l10','belong to','',NULL,'/bɪˈlɔːŋ tə/','It has belonged to my family for generations.','它在我家传了好几代。','This book belongs to me.','这本书是我的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l10','be allowed to','',NULL,'/bi əˈlaʊd tə/','None of us are allowed to touch it.','我们谁也不许碰它。','You are allowed to leave early today.','你今天可以早走。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp1','choice','{"stem":"被动语态的谓语动词由什么构成?","options":["have + 过去分词","be + 现在分词","be + 过去分词","情态动词 + 原形"],"answer_index":2,"explanation_cn":"被动语态的谓语 = be + 过去分词(表示\"被…\")。✓ It was made in Germany.(be=was,过去分词=made)"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp1','choice','{"stem":"\"The instrument ___ made in Germany.\"(一般过去被动,单数)","options":["is","was","were","has"],"answer_index":1,"explanation_cn":"一般过去被动 = was/were + 过去分词;The instrument 是单数,用 was。✓ The instrument was made in Germany."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp2','choice','{"stem":"\"This song ___ by many people.\"(一般现在被动,单数)","options":["sings","is singing","is sung","sang"],"answer_index":2,"explanation_cn":"一般现在被动 = is/are + 过去分词;This song 单数,用 is sung。✓ This song is sung by many people."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp2','choice','{"stem":"\"Our papers ___ every morning.\"(deliver,一般现在被动,复数)","options":["delivers","is delivered","deliver","are delivered"],"answer_index":3,"explanation_cn":"一般现在被动;Our papers 是复数,用 are + 过去分词 delivered。✓ Our papers are delivered every morning."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp3','choice','{"stem":"\"The bridge ___ in 1942.\"(build,一般过去被动)","options":["was build","was built","is built","built"],"answer_index":1,"explanation_cn":"一般过去被动 = was/were + 过去分词;build 的过去分词是 built。✓ The bridge was built in 1942."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp3','choice','{"stem":"\"Two strings ___ by the visitor.\"(break,一般过去被动,复数)","options":["are broken","broke","were broken","was broken"],"answer_index":2,"explanation_cn":"Two strings 是复数,一般过去被动用 were + 过去分词 broken。✓ Two strings were broken."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp3','choice','{"stem":"\"The clavichord ___ by my grandpa.\"(buy,一般过去被动)","options":["bought","was bought","is bought","was buy"],"answer_index":1,"explanation_cn":"一般过去被动;buy 的过去分词是 bought。✓ The clavichord was bought by my grandpa."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp4','choice','{"stem":"\"This bridge was built ___ prisoners of war.\"(指出谁建的)","options":["from","with","of","by"],"answer_index":3,"explanation_cn":"被动句里,要指出\"动作是谁做的\",用 by + 动作执行者。✓ was built by prisoners of war."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp4','choice','{"stem":"被动句里要指出\"动作是谁做的\",用:","options":["with + 动作执行者","by + 动作执行者","for + 动作执行者","to + 动作执行者"],"answer_index":1,"explanation_cn":"被动句想说清\"谁做的\",用 by + 动作执行者。✓ It was bought by my grandpa."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp5','choice','{"stem":"把 \"The police arrested the thief.\" 变成被动语态:","options":["The thief was arrested (by the police).","The thief arrested the police.","The police was arrested.","The thief was arrest."],"answer_index":0,"explanation_cn":"主动变被动:原来的宾语 the thief 挪到前面当主角,动词变 was arrested,原来的主语 the police 放到 by 后面。✓"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp5','choice','{"stem":"主动句变被动句,原来的宾语要变成:","options":["保持不变","被动句的主语(挪到前面)","by 后面的词","被动句的宾语"],"answer_index":1,"explanation_cn":"主动句变被动句时,原来动作的承受者(宾语)要挪到句首,成为被动句的主语。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp5','choice','{"stem":"把 \"Workmen built the road.\" 变成被动语态:","options":["The workmen was built.","The road built by workmen.","The road was built by workmen.","The road was build by workmen."],"answer_index":2,"explanation_cn":"主动 Workmen built the road → 被动:the road 当主语,built→was built,workmen 放 by 后。✓ The road was built by workmen."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp6','choice','{"stem":"\"我们不许碰它\"的正确说法(be not allowed):","options":["We not are allowed to touch it.","We are not allow to touch it.","We do not allowed to touch it.","We are not allowed to touch it."],"answer_index":3,"explanation_cn":"被动否定 = be + not + 过去分词;allow 的过去分词 allowed。✓ We are not allowed to touch it."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp6','choice','{"stem":"下面哪一句是被动语态?","options":["Tom will write a letter.","The letter was written by Tom.","Tom wrote the letter.","Tom is writing a letter."],"answer_index":1,"explanation_cn":"被动语态形如 be + 过去分词(was written)。其它三句都是主动语态。✓ The letter was written by Tom."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp6','choice','{"stem":"被动语态的时态,是靠改变哪个词来体现的?","options":["过去分词","by 后面的词","be 动词","句子的主角"],"answer_index":2,"explanation_cn":"被动语态的时态靠改变 be(is/was/will be/has been…)来体现;过去分词永远不变。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp7','choice','{"stem":"\"我姐姐的书\"用英语说:","options":["my sisters book","my sister''s book","the book of my sister''s","my sister book''s"],"answer_index":1,"explanation_cn":"表示\"某人的\"用名词 + ''s;\"我姐姐的书\" = my sister''s book。✓"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp7','choice','{"stem":"\"这首歌的名字\"(无生命,常用 of):","options":["the name of the song","the song name","the song''s name of","of the song name"],"answer_index":0,"explanation_cn":"无生命的东西(歌、书等)表示所属,常用 of 属格:the name of the song = 这首歌的名字。✓"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',5,'am2_l10_gp8','choice','{"stem":"\"我父亲的一位朋友\"(双重所有格,''s 和 of 同用):","options":["a friend of my father","a father''s friend of","my father a friend","a friend of my father''s"],"answer_index":3,"explanation_cn":"双重所有格:of 和 ''s 同用,表示\"…的其中一位\"。\"我父亲的一位朋友\" = a friend of my father''s。✓"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',6,NULL,'choice','{"stem":"美语里\"客厅\"用:","options":["lounge","living room","sitting room","hall"],"answer_index":1,"explanation_cn":"美语\"客厅\"用 living room;英式用 sitting room。✓ kept in the living room."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',6,NULL,'choice','{"stem":"美语里\"爷爷(口语)\"用:","options":["grandpa","grandad","granddad","grandfa"],"answer_index":0,"explanation_cn":"美语\"爷爷/外公\"口语用 grandpa;英式用 grandad。✓ my grandpa bought it."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',6,NULL,'choice','{"stem":"动词\"练习\"的美式拼写是:","options":["practise","practis","practicing","practice"],"answer_index":3,"explanation_cn":"\"练习\"作动词,美式拼 practice;英式动词拼 practise。✓ practice jazz."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',6,NULL,'choice','{"stem":"be made in 的意思是:","options":["被拿走","在…制造 / 产自…","被弄坏","被展示"],"answer_index":1,"explanation_cn":"be made in = 在…制造、产自…。✓ It was made in Germany."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',6,NULL,'choice','{"stem":"belong to 的意思是:","options":["属于","送给","来自","离开"],"answer_index":0,"explanation_cn":"belong to = 属于。✓ It has belonged to my family."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',6,NULL,'choice','{"stem":"be allowed to 的意思是:","options":["被要求","被邀请","被禁止","被允许(做某事)"],"answer_index":3,"explanation_cn":"be allowed to = 被允许做某事。✓ We are not allowed to touch it."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',7,NULL,'cloze','{"stem":"第 1 空","context":"The old clavichord ___1___ made in Germany. It ___2___ bought by my grandpa. Recently it ___3___ damaged by a visitor, and two strings ___4___ broken.","blank_no":1,"options":["was","is","were","has"],"answer_index":0,"explanation_cn":"一般过去被动;It(古钢琴)单数,用 was + 过去分词 made。✓ It was made in Germany."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',7,NULL,'cloze','{"stem":"第 2 空","context":"The old clavichord ___1___ made in Germany. It ___2___ bought by my grandpa. Recently it ___3___ damaged by a visitor, and two strings ___4___ broken.","blank_no":2,"options":["was","is","were","did"],"answer_index":0,"explanation_cn":"一般过去被动;was + 过去分词 bought。✓ It was bought by my grandpa."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',7,NULL,'cloze','{"stem":"第 3 空","context":"The old clavichord ___1___ made in Germany. It ___2___ bought by my grandpa. Recently it ___3___ damaged by a visitor, and two strings ___4___ broken.","blank_no":3,"options":["was","is","were","had"],"answer_index":0,"explanation_cn":"一般过去被动;was + 过去分词 damaged。✓ Recently it was damaged."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',7,NULL,'cloze','{"stem":"第 4 空","context":"The old clavichord ___1___ made in Germany. It ___2___ bought by my grandpa. Recently it ___3___ damaged by a visitor, and two strings ___4___ broken.","blank_no":4,"options":["were","was","is","has"],"answer_index":0,"explanation_cn":"two strings 是复数,一般过去被动用 were + 过去分词 broken。✓ Two strings were broken."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',8,NULL,'choice','{"stem":"Where was the clavichord made?","options":["In France","In China","In America","In Germany"],"answer_index":3,"explanation_cn":"课文说 It was made in Germany,古钢琴产自德国。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',8,NULL,'choice','{"stem":"What did the visitor try to do?","options":["Clean it","Fix it","Play jazz on it","Sell it"],"answer_index":2,"explanation_cn":"课文说 She wanted to practice jazz on it,客人想用它弹爵士乐。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',8,NULL,'choice','{"stem":"Who is repairing the clavichord now?","options":["A friend of the writer''s dad","A music teacher","The visitor","The grandpa"],"answer_index":0,"explanation_cn":"课文说 It is being repaired by a friend of my dad''s,是作者爸爸的一位朋友在修。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',9,NULL,'choice','{"stem":"你想说\"这座桥是1990年建的\"(强调桥,用被动):","options":["This bridge was build in 1990.","This bridge is build in 1990.","This bridge was built in 1990.","This bridge built in 1990."],"answer_index":2,"explanation_cn":"想突出\"桥\"这个被建造的东西,用被动 was built(be+过去分词)。✓ This bridge was built in 1990. 场合:介绍一座桥的来历。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',9,NULL,'choice','{"stem":"你想说\"我的自行车被偷了\"(被动):","options":["My bike is stealing.","My bike stole.","My bike was steal.","My bike was stolen."],"answer_index":3,"explanation_cn":"\"车被偷了\",车是被偷的一方,用被动 was stolen。✓ My bike was stolen. 场合:告诉别人你的车丢了。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',9,NULL,'choice','{"stem":"你想说\"这儿不许拍照\"(be not allowed):","options":["Photos are not allowed here.","Photos do not allowed here.","Photos are not allow here.","Photos not allow here."],"answer_index":0,"explanation_cn":"\"不许拍照\",照片是被禁止的一方,用被动否定 are not allowed。✓ Photos are not allowed here. 场合:提醒别人这里禁止拍照。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',10,NULL,'choice','{"stem":"damage 的意思是:","options":["修理","损坏","展示","购买"],"answer_index":1,"explanation_cn":"damage = 损坏。✓ It was damaged by a visitor."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',10,NULL,'choice','{"stem":"allow 的意思是:","options":["命令","拒绝","禁止","允许"],"answer_index":3,"explanation_cn":"allow = 允许、让。✓ We are not allowed to touch it."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',10,NULL,'choice','{"stem":"\"The window ___ by the boy.\"(break,一般过去被动)","options":["was broken","breaks","was break","broke"],"answer_index":0,"explanation_cn":"一般过去被动 = was + 过去分词 broken。✓ The window was broken by the boy."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',10,NULL,'choice','{"stem":"\"Rice ___ in many countries.\"(grow,一般现在被动)","options":["is growing","is grown","grows","grew"],"answer_index":1,"explanation_cn":"一般现在被动 = is + 过去分词 grown;Rice 不可数按单数,用 is grown。✓ Rice is grown in many countries."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',10,NULL,'choice','{"stem":"\"This house was built 100 years ago.\" 的意思是:","options":["有人100年前住这儿","这房子要建100年","这房子是100年前建的","这房子有100间房"],"answer_index":2,"explanation_cn":"This house was built 100 years ago = 这房子是100年前建成的(强调房子被建)。场合:讲一栋老房子的历史。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',10,NULL,'choice','{"stem":"\"a friend of my father''s\" 的意思是:","options":["我和父亲的朋友","我父亲的一位朋友","我父亲的所有朋友","一位朋友的父亲"],"answer_index":1,"explanation_cn":"a friend of my father''s = 我父亲的众多朋友中的一位。场合:向别人介绍来的是谁。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',10,NULL,'choice','{"stem":"Why was the clavichord damaged?","options":["A visitor struck the keys too hard playing jazz","It was too old","It fell down","Nobody cleaned it"],"answer_index":0,"passage":"My family owns an old musical instrument called a clavichord. It was made in Germany over three hundred years ago. The clavichord is kept in our living room. It has belonged to my family for generations. It was bought by my grandpa a long time ago. Recently, it was damaged by a visitor. She wanted to practice jazz on it and struck the keys too hard. Two of the strings were broken, and my dad was shocked. Now none of us are allowed to touch it. It is being repaired by a friend of my dad''s. Soon we will be able to play it again.","explanation_cn":"课文说客人想弹爵士、击键太重,把琴弄坏了。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',10,NULL,'choice','{"stem":"Can the family touch the clavichord now?","options":["Yes, but carefully","Only the grandpa can","Yes, anytime","No, none of them are allowed to touch it"],"answer_index":3,"passage":"My family owns an old musical instrument called a clavichord. It was made in Germany over three hundred years ago. The clavichord is kept in our living room. It has belonged to my family for generations. It was bought by my grandpa a long time ago. Recently, it was damaged by a visitor. She wanted to practice jazz on it and struck the keys too hard. Two of the strings were broken, and my dad was shocked. Now none of us are allowed to touch it. It is being repaired by a friend of my dad''s. Soon we will be able to play it again.","explanation_cn":"课文说 Now none of us are allowed to touch it,现在谁都不许碰。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',10,NULL,'choice','{"stem":"Who bought the clavichord?","options":["The writer''s grandpa","The writer''s dad","A friend","A visitor"],"answer_index":0,"audio":"My family owns an old musical instrument called a clavichord. It was made in Germany over three hundred years ago. The clavichord is kept in our living room. It has belonged to my family for generations. It was bought by my grandpa a long time ago. Recently, it was damaged by a visitor. She wanted to practice jazz on it and struck the keys too hard. Two of the strings were broken, and my dad was shocked. Now none of us are allowed to touch it. It is being repaired by a friend of my dad''s. Soon we will be able to play it again.","explanation_cn":"课文说 It was bought by my grandpa,是作者的爷爷买的。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l10',10,NULL,'choice','{"stem":"What was broken?","options":["The whole instrument","The lid","Two of the strings","Two keys"],"answer_index":2,"audio":"My family owns an old musical instrument called a clavichord. It was made in Germany over three hundred years ago. The clavichord is kept in our living room. It has belonged to my family for generations. It was bought by my grandpa a long time ago. Recently, it was damaged by a visitor. She wanted to practice jazz on it and struck the keys too hard. Two of the strings were broken, and my dad was shocked. Now none of us are allowed to touch it. It is being repaired by a friend of my dad''s. Soon we will be able to play it again.","explanation_cn":"课文说 Two of the strings were broken,断的是两根弦。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l11',2,2,11,'One good turn deserves another','礼尚往来','时态语态综合复习(主考:一般现在/现在进行/一般过去/现在完成/过去进行/被动 · 依语境选时态)+ 并列连词 and/but/for/so(辅考)+ v.+sb+to do 宾补(辅考)','餐馆里遇到从不还钱的老熟人托尼 · 借他二十美元 · 反被他借势"礼尚往来"让作者付账','{"q":"Listen and answer — Who paid for the writer''s dinner?","options":["The writer did (Tony turned it around)","Tony paid","They split it","The restaurant gave it free"],"answer_index":0}'::jsonb,'{"title":"怎么选时态——看语境和时间状语(复习)","intro":"本课把前面学过的时态语态放在一起复习。挑时态的关键不是背规则,而是看句子说的是什么时候、什么样的事。全用本课句子举例。","table":{"headers":["什么时候 / 什么样的事","用哪个时态 · 本课例子"],"rows":[["此刻 / 现阶段正在进行","现在进行(is/are + doing):He is now working at a bank."],["通常 / 反复发生的习惯","一般现在(do/does):He gets a good salary but always borrows money."],["过去某个时间完成的动作","一般过去(did):Tony walked in. / He gave me the money."],["到现在为止的经历 / 影响","现在完成(has/have + done):He has never borrowed money from me."],["过去某一刻正在进行","过去进行(was/were + doing):While he was eating, I asked him…"]]},"specialRules":[{"rule":"''某物被…''用被动语态(be + 过去分词),是前面第10课学的,本课一起复习","mark":"被动复习"},{"rule":"选时态先找时间信号:now→现在进行 · always/every day→一般现在 · years ago→一般过去 · never/so far→现在完成 · when/while + 过去→过去进行","mark":"看时间信号"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l11',1,NULL,'I was having dinner at a downtown restaurant when Tony Steele walked in.','我正在市中心一家餐馆吃饭,这时托尼·斯蒂尔走了进来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l11',2,NULL,'Tony worked in a lawyer''s office years ago, but he is now working at a bank.','托尼几年前在一家律师事务所工作,不过现在在一家银行上班。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l11',3,NULL,'He gets a good salary, but he always borrows money from his friends and never pays it back.','他薪水不低,却总是向朋友借钱,而且从不归还。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l11',4,NULL,'Tony saw me, and he came over and sat down at my table.','托尼看见了我,就走过来坐到了我这桌。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l11',5,NULL,'He has never borrowed a single dollar from me before.','他以前从没向我借过一分钱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l11',6,NULL,'While he was eating, I asked him to lend me twenty dollars.','趁他吃饭的时候,我请他借给我二十美元。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l11',7,NULL,'To my surprise, he handed me the money immediately.','令我意外的是,他立刻把钱递给了我。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l11',8,NULL,'"I have never borrowed any money from you," Tony said with a smile.','"我可从没向你借过钱,"托尼笑着说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l11',9,NULL,'"So now you can pay for my dinner!"','"所以现在你可以替我付这顿饭钱啦!"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l11',10,NULL,'I looked at the check on the table and could not help laughing.','我看着桌上的账单,忍不住笑了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l11',11,NULL,'One good turn deserves another, I guess.','礼尚往来嘛,我想。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l11','turn','/tɜːrn/','n','行为,举止','One good turn deserves another.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l11','deserve','/dɪˈzɜːrv/','v','应得,值得','One good turn deserves another.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l11','lawyer','/ˈlɔːjər/','n','律师','He worked in a lawyer''s office.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l11','bank','/bæŋk/','n','银行','He is now working at a bank.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l11','salary','/ˈsæləri/','n','工资,薪水','He gets a good salary.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l11','immediately','/ɪˈmiːdiətli/','adv','立刻,马上','He handed me the money immediately.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
