INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l11_gp3','am2_l11','复习——现在完成 vs 一般过去(has never borrowed vs worked)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l11_gp4','am2_l11','复习——过去进行时(was having…when / while…was eating)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
