INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l11','dollars','pounds','货币;美语版用 dollars(美元),英式原文 pounds(英镑)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l11','the check','the bill','餐馆账单;美语说 the check,英式说 the bill') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l11','attorney','lawyer','律师;美语常说 attorney,英式多说 lawyer(课文保留 lawyer 教官方词)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l11','to my surprise','',NULL,'/tə maɪ sərˈpraɪz/','To my surprise, he handed me the money immediately.','令我意外的是,他立刻把钱递给了我。','To my surprise, the test was easy.','令我意外的是,考试很简单。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l11','borrow ... from','',NULL,'/ˈbɑːroʊ frəm/','He borrows money from his friends.','他向朋友借钱。','I borrowed a book from the library.','我从图书馆借了一本书。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l11','pay for','',NULL,'/peɪ fər/','Now you can pay for my dinner.','现在你可以替我付饭钱了。','Let me pay for the coffee.','咖啡我来付。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp1','choice','{"stem":"现在进行时(is/are + doing)表示什么时候的动作?","options":["过去某一刻正在进行","到现在为止的经历","此刻 / 现阶段正在进行","通常反复发生的习惯"],"answer_index":2,"explanation_cn":"现在进行时(is/are + doing)表示\"此刻正在做\"或\"这段时间正在做\"的事。✓ He is now working at a bank.(现阶段在银行上班)"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp1','choice','{"stem":"\"Tony worked in an office before, but he ___ at a bank now.\"(now → 现在进行)","options":["has worked","works","worked","is working"],"answer_index":3,"explanation_cn":"句尾 now 是\"现在\"的信号,表示现阶段正在做的事,用现在进行时 is working。✓ He is now working at a bank."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp2','choice','{"stem":"\"Tony ___ in a lawyer''s office years ago.\"(years ago → 一般过去)","options":["is working","works","worked","has worked"],"answer_index":2,"explanation_cn":"years ago(几年前)是明确的过去时间,用一般过去时 worked。✓ Tony worked in a lawyer''s office years ago."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp2','choice','{"stem":"\"To my surprise, he ___ me the money immediately.\"(give,过去完成的动作)","options":["gave","is giving","gives","has given"],"answer_index":0,"explanation_cn":"give 的过去式是 gave;这是过去已经完成的动作,用一般过去时。✓ To my surprise, he gave me the money immediately."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp3','choice','{"stem":"\"He ___ money from me before.\"(never,到现在为止的经历 → 现在完成)","options":["is never borrowing","never borrows","has never borrowed","never borrowed"],"answer_index":2,"explanation_cn":"never(从没)强调从过去到现在的经历,用现在完成时 has + 过去分词 borrowed。✓ He has never borrowed money from me before."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp3','choice','{"stem":"有明确的过去时间(years ago)时,该用一般过去还是现在完成?","options":["一般过去(worked)","两个都行","现在完成(has worked)","现在进行(is working)"],"answer_index":0,"explanation_cn":"句子里有明确的过去时间(years ago)时,用一般过去时,不用现在完成时。现在完成时不与明确的过去时间连用。✓ Tony worked… years ago."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp4','choice','{"stem":"\"I ___ dinner when Tony walked in.\"(have,过去某刻正在进行 → 过去进行)","options":["have had","was having","had","am having"],"answer_index":1,"explanation_cn":"\"当托尼走进来时,我正在吃饭\"——过去某一刻正在进行的事,用过去进行时 was having。✓ I was having dinner when Tony walked in."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp4','choice','{"stem":"\"___ he was eating, I asked him to lend me money.\"(过去某段时间正在进行)","options":["Before","Since","After","While"],"answer_index":3,"explanation_cn":"\"趁他吃饭的时候\"表示过去某段时间里正在进行,用 While 引出。✓ While he was eating, I asked him to lend me money."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp5','choice','{"stem":"\"This bridge ___ in 1990.\"(build,某物''被建'' → 被动语态复习)","options":["builds","was built","built","was build"],"answer_index":1,"explanation_cn":"\"桥被建\"——某物被别人怎么样,用被动语态 be + 过去分词;build 的过去分词是 built,一般过去被动用 was built。✓ This bridge was built in 1990.(第10课被动语态复习)"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp6','choice','{"stem":"挑时态时,最该看的是什么?","options":["句子的长短","有没有生词","句子里的时间信号和上下文语境","主语是不是人"],"answer_index":2,"explanation_cn":"挑时态别死背规则,先看句子里的时间信号(now / always / years ago / never / when…)和整句说的是什么时候的事。✓"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp6','choice','{"stem":"\"Listen! Someone ___ at the door.\"(Listen! → 此刻正在)","options":["knocks","knocked","has knocked","is knocking"],"answer_index":3,"explanation_cn":"Listen!(听!)说明说话此刻正在发生,用现在进行时 is knocking。✓ Listen! Someone is knocking at the door."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp7','choice','{"stem":"\"Tony saw me, ___ he came over and sat down.\"(两件事相加 → 并列)","options":["and","for","so","but"],"answer_index":0,"explanation_cn":"\"托尼看见我\"和\"他走过来坐下\"是接连发生、意思相加的两件事,用并列连词 and 连接。✓ Tony saw me, and he came over and sat down."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp7','choice','{"stem":"\"He gets a good salary, ___ he always borrows money.\"(前后相反 → 转折)","options":["or","so","but","and"],"answer_index":2,"explanation_cn":"\"薪水不低\"和\"总向朋友借钱\"前后意思相反,用表示转折的 but。✓ He gets a good salary, but he always borrows money."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp7','choice','{"stem":"\"Now you can pay for my dinner!\" —— 前因后果,''所以''用:","options":["for","or","but","so"],"answer_index":3,"explanation_cn":"\"你可以替我付饭钱了\"是前面事情的结果,\"所以\"用 so。✓ So now you can pay for my dinner!"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp7','choice','{"stem":"\"He didn''t buy the car, ___ he was short of money.\"(表原因)","options":["but","or","for","so"],"answer_index":2,"explanation_cn":"\"他没买车\"和\"他缺钱\"是结果与原因的关系,for 表示原因(因为)。✓ He didn''t buy the car, for he was short of money."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp8','choice','{"stem":"ask sb ___ sth（请某人做某事）,''某人''后面的动作用:","options":["do(原形)","to do(不定式)","did","doing"],"answer_index":1,"explanation_cn":"ask sb to do sth = 请某人做某事;\"某人\"后面的动作用不定式 to do。✓ I asked him to lend me money."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp8','choice','{"stem":"\"I asked him ___ me twenty dollars.\"(ask sb to do)","options":["lending","lend","lent","to lend"],"answer_index":3,"explanation_cn":"ask sb to do 结构里,him 后面用不定式 to lend。✓ I asked him to lend me twenty dollars."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',5,'am2_l11_gp8','choice','{"stem":"\"The teacher wants us ___ hard.\"(want sb to do)","options":["working","works","to work","work"],"answer_index":2,"explanation_cn":"want sb to do sth = 想让某人做某事;us 后面用不定式 to work。✓ The teacher wants us to work hard."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',6,NULL,'choice','{"stem":"美语版把 twenty pounds 换成美元,用:","options":["pounds","coins","dollars","cents"],"answer_index":2,"explanation_cn":"美国用美元 dollars 结算;英式原文里的 twenty pounds(英镑),美语版改成 twenty dollars。✓"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',6,NULL,'choice','{"stem":"美语里\"餐馆账单\"用:","options":["the note","the check","the ticket","the bill"],"answer_index":1,"explanation_cn":"在美国餐馆结账,账单叫 the check;英式叫 the bill。✓ Can I have the check, please?"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',6,NULL,'choice','{"stem":"美语里\"律师\"除了 lawyer,还常说:","options":["attorney","barrister","advocate","solicitor"],"answer_index":0,"explanation_cn":"美语里\"律师\"除了 lawyer,还常说 attorney;solicitor、barrister 是英式说法。✓"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',6,NULL,'choice','{"stem":"to my surprise 的意思是:","options":["在我看来","对我来说","令我惊讶的是","据我所知"],"answer_index":2,"explanation_cn":"to my surprise = 令我惊讶的是、出乎我意料。✓ To my surprise, he handed me the money."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',6,NULL,'choice','{"stem":"borrow … from 的意思是:","options":["还给…","买下…","借出给…","向…借入"],"answer_index":3,"explanation_cn":"borrow … from = 向某人/某处借入(东西到自己这儿)。✓ He borrows money from his friends."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',6,NULL,'choice','{"stem":"pay for 的意思是:","options":["为…付款","讨价还价","赚取","偿还欠款"],"answer_index":0,"explanation_cn":"pay for = 为某样东西付钱。✓ Now you can pay for my dinner."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',7,NULL,'cloze','{"stem":"第 1 空","context":"Tony ___1___ in a lawyer''s office years ago, but now he ___2___ at a bank. While he ___3___ dinner, I asked him to lend me twenty dollars. He ___4___ never borrowed money from me before.","blank_no":1,"options":["worked","works","is working","has worked"],"answer_index":0,"explanation_cn":"years ago 是过去时间,用一般过去时 worked。✓ Tony worked in a lawyer''s office years ago."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',7,NULL,'cloze','{"stem":"第 2 空","context":"Tony ___1___ in a lawyer''s office years ago, but now he ___2___ at a bank. While he ___3___ dinner, I asked him to lend me twenty dollars. He ___4___ never borrowed money from me before.","blank_no":2,"options":["is working","works","worked","was working"],"answer_index":0,"explanation_cn":"now 表示现阶段,用现在进行时 is working。✓ Now he is working at a bank."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',7,NULL,'cloze','{"stem":"第 3 空","context":"Tony ___1___ in a lawyer''s office years ago, but now he ___2___ at a bank. While he ___3___ dinner, I asked him to lend me twenty dollars. He ___4___ never borrowed money from me before.","blank_no":3,"options":["was having","had","has","is having"],"answer_index":0,"explanation_cn":"While + 过去某段时间正在进行,用过去进行时 was having。✓ While he was having dinner…"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',7,NULL,'cloze','{"stem":"第 4 空","context":"Tony ___1___ in a lawyer''s office years ago, but now he ___2___ at a bank. While he ___3___ dinner, I asked him to lend me twenty dollars. He ___4___ never borrowed money from me before.","blank_no":4,"options":["has","had","is","was"],"answer_index":0,"explanation_cn":"never borrowed…before 强调到现在的经历,用现在完成时 has + 过去分词。✓ He has never borrowed money from me before."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',8,NULL,'choice','{"stem":"Where is Tony working now?","options":["In a lawyer''s office","In a school","At a restaurant","At a bank"],"answer_index":3,"explanation_cn":"课文说 he is now working at a bank,托尼现在在银行上班。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',8,NULL,'choice','{"stem":"How much did the writer ask to borrow?","options":["Twenty dollars","Twenty pounds","Fifty dollars","Ten dollars"],"answer_index":0,"explanation_cn":"课文说 I asked him to lend me twenty dollars,作者想借二十美元。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',8,NULL,'choice','{"stem":"Who paid for the dinner in the end?","options":["Tony","The writer","The restaurant","They split it"],"answer_index":1,"explanation_cn":"托尼借势说\"现在你可以替我付饭钱了\",结果是作者付了这顿饭。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',9,NULL,'choice','{"stem":"你想说\"我此刻正在写作业\"(此刻正在做的事):","options":["I did my homework now.","I do my homework now.","I have done my homework now.","I am doing my homework now."],"answer_index":3,"explanation_cn":"\"此刻正在做作业\",用现在进行时 am doing。✓ I am doing my homework now. 场合:别人叫你时说明你正忙。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',9,NULL,'choice','{"stem":"你想说\"我到家时,妈妈正在做饭\"(过去某一刻正在做的事):","options":["When I got home, my mom cooks.","When I got home, my mom was cooking.","When I got home, my mom cooked.","When I got home, my mom has cooked."],"answer_index":1,"explanation_cn":"\"我到家时妈妈正在做饭\"——过去某一刻正在进行的事,用过去进行时 was cooking。✓ 场合:描述回到家看到的情景。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',9,NULL,'choice','{"stem":"你想说\"我从没去过北京\"(到现在为止的经历):","options":["I have never been to Beijing.","I was never in Beijing.","I never go to Beijing.","I am never in Beijing."],"answer_index":0,"explanation_cn":"\"从没去过北京\"强调到现在为止的经历,用现在完成时 have never been。✓ 场合:聊自己去过哪些地方。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',10,NULL,'choice','{"stem":"deserve 的意思是:","options":["应得,值得","保存","应付了事","服务"],"answer_index":0,"explanation_cn":"deserve = 应得到、值得。✓ One good turn deserves another.(好心有好报 / 礼尚往来)"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',10,NULL,'choice','{"stem":"immediately 的意思是:","options":["偶尔","立刻,马上","慢慢地","最近"],"answer_index":1,"explanation_cn":"immediately = 立刻、马上。✓ He handed me the money immediately."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',10,NULL,'choice','{"stem":"\"He ___ money from his friends every week.\"(every week,习惯 → 一般现在)","options":["is borrowing","borrowed","borrows","has borrowed"],"answer_index":2,"explanation_cn":"every week(每周)说明是反复的习惯,用一般现在时 borrows。✓ He borrows money from his friends every week."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',10,NULL,'choice','{"stem":"\"I ___ TV when the phone rang.\"(过去某刻正在 → 过去进行)","options":["have watched","was watching","watched","watch"],"answer_index":1,"explanation_cn":"when the phone rang(电话响时)我正在看电视——过去某一刻正在进行,用过去进行时 was watching。✓"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',10,NULL,'choice','{"stem":"\"He is rich, ___ he is not happy.\" 中间填哪个词(前后意思相反)?","options":["but","and","so","for"],"answer_index":0,"explanation_cn":"\"他很有钱\"和\"他不快乐\"前后意思相反,中间用\"但是\"——but。✓ He is rich, but he is not happy."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',10,NULL,'choice','{"stem":"\"My mom told me ___ early.\"(告诉某人做某事)横线上填:","options":["come","coming","came","to come"],"answer_index":3,"explanation_cn":"\"妈妈告诉我早点来\"——告诉某人做某事,某人后面的动作用不定式 to come。✓ My mom told me to come early."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',10,NULL,'choice','{"stem":"What does Tony always do with money he borrows from friends?","options":["He saves it in the bank","He borrows it and never pays it back","He pays it back the next day","He gives it away"],"answer_index":1,"passage":"I was having dinner at a downtown restaurant when Tony Steele walked in. Tony worked in a lawyer''s office years ago, but he is now working at a bank. He gets a good salary, but he always borrows money from his friends and never pays it back. Tony saw me, and he came over and sat down at my table. He has never borrowed a single dollar from me before. While he was eating, I asked him to lend me twenty dollars. To my surprise, he handed me the money immediately. \"I have never borrowed any money from you,\" Tony said with a smile. \"So now you can pay for my dinner!\" I looked at the check on the table and could not help laughing. One good turn deserves another, I guess.","explanation_cn":"课文说 he always borrows money from his friends and never pays it back,托尼借了钱从不归还。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',10,NULL,'choice','{"stem":"How did the writer end up paying for the dinner?","options":["Tony paid and left","The writer offered to pay first","They shared the bill equally","After borrowing, Tony said the writer could pay for his dinner"],"answer_index":3,"passage":"I was having dinner at a downtown restaurant when Tony Steele walked in. Tony worked in a lawyer''s office years ago, but he is now working at a bank. He gets a good salary, but he always borrows money from his friends and never pays it back. Tony saw me, and he came over and sat down at my table. He has never borrowed a single dollar from me before. While he was eating, I asked him to lend me twenty dollars. To my surprise, he handed me the money immediately. \"I have never borrowed any money from you,\" Tony said with a smile. \"So now you can pay for my dinner!\" I looked at the check on the table and could not help laughing. One good turn deserves another, I guess.","explanation_cn":"托尼借了作者的钱后打趣说\"我从没向你借过钱,所以现在你可以替我付饭钱\",把账巧妙推给了作者。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',10,NULL,'choice','{"stem":"What was Tony''s job years ago?","options":["He was a waiter","He was a driver","He worked in a lawyer''s office","He worked at a bank"],"answer_index":2,"audio":"I was having dinner at a downtown restaurant when Tony Steele walked in. Tony worked in a lawyer''s office years ago, but he is now working at a bank. He gets a good salary, but he always borrows money from his friends and never pays it back. Tony saw me, and he came over and sat down at my table. He has never borrowed a single dollar from me before. While he was eating, I asked him to lend me twenty dollars. To my surprise, he handed me the money immediately. \"I have never borrowed any money from you,\" Tony said with a smile. \"So now you can pay for my dinner!\" I looked at the check on the table and could not help laughing. One good turn deserves another, I guess.","explanation_cn":"课文说 Tony worked in a lawyer''s office years ago,托尼几年前在律师事务所工作。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l11',10,NULL,'choice','{"stem":"What did Tony do when the writer asked to borrow money?","options":["He walked away","He gave the money immediately","He refused","He asked why"],"answer_index":1,"audio":"I was having dinner at a downtown restaurant when Tony Steele walked in. Tony worked in a lawyer''s office years ago, but he is now working at a bank. He gets a good salary, but he always borrows money from his friends and never pays it back. Tony saw me, and he came over and sat down at my table. He has never borrowed a single dollar from me before. While he was eating, I asked him to lend me twenty dollars. To my surprise, he handed me the money immediately. \"I have never borrowed any money from you,\" Tony said with a smile. \"So now you can pay for my dinner!\" I looked at the check on the table and could not help laughing. One good turn deserves another, I guess.","explanation_cn":"课文说 To my surprise, he handed me the money immediately,托尼立刻就把钱给了作者。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l12',2,2,12,'Goodbye and good luck','再见,一路顺风','一般将来时(主考:will/shall+动词原形 · ''ll缩略 · 各人称 · will be · 否定won''t · 疑问Will…? · shall提议 · 过去→将来改写)+ be going to(辅考讲深)+ 一般现在·现在进行表将来(辅考讲深)','邻居船长明天启航 · 独自驾小帆船横渡大洋参加比赛 · 大家去码头送行、道别、加油','{"q":"Listen and answer — Where is Captain Reed going, and how?","options":["Across the ocean, on his little sailboat","To another city, by train","To an island, by plane","Nowhere, he will stay home"],"answer_index":0}'::jsonb,'{"title":"说\"将来要做什么\"(一般将来时)","intro":"本课讲怎么说\"将来要发生、将来要做的事\"——一般将来时。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["一般将来时 = will + 动词原形(表示''将要…'')","Captain Reed will sail tomorrow.(明天将起航)"],["shall 也可代 will,常用于第一人称 I / we","Shall we go now?(我们走吧?)"],["口语里 will 常缩略为 ''ll(I''ll / he''ll / we''ll / they''ll)","We''ll say goodbye to him.(我们会跟他道别)"],["将来的状态 / 位置用 will be","He will be away for two months.(他将离开两个月)"],["否定:won''t(will not);疑问:把 will 提前(Will he…?)","She won''t be late. / Will he leave tomorrow?"]]},"specialRules":[{"rule":"be going to + 动词原形:表示计划好、打算要做的事,或有迹象很可能发生","mark":"be going to"},{"rule":"时刻表用一般现在时、已安排好的事用现在进行时,也能表将来(The train leaves at 8 / We are having a party Friday)","mark":"现在时表将来"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l12',1,NULL,'Our neighbor, Captain David Reed, will sail from the harbor tomorrow morning.','我们的邻居戴维·里德船长明天早上就要起航了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l12',2,NULL,'We are going to meet him at the dock bright and early.','我们打算一大早就到码头为他送行。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l12',3,NULL,'He will be on his little sailboat, the Seabird.','他将乘坐他那艘名叫"海鸟号"的小帆船。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l12',4,NULL,'The Seabird is a famous little boat, and it has crossed the Atlantic many times.','"海鸟号"是艘有名的小船,已经多次横渡大西洋。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l12',5,NULL,'Captain Reed will set out at eight o''clock sharp, so we''ll have plenty of time.','里德船长将于八点整启程,所以我们时间很充裕。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l12',6,NULL,'We''ll watch his boat leave, and then we''ll say goodbye to him.','我们会目送他的船离开,然后跟他道别。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l12',7,NULL,'"Good luck!" we will all shout from the dock.','"祝你好运!"我们会一起在码头上喊。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l12',8,NULL,'He is going to be away for about two months.','他将要离开大约两个月。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l12',9,NULL,'We are all very proud of him.','我们都为他感到骄傲。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l12',10,NULL,'He will take part in an important race across the ocean.','他将参加一场横渡大洋的重要比赛。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l12',11,NULL,'I think he will win, and we will welcome him home like a hero.','我想他会赢,到时我们会像迎接英雄一样迎他回家。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
