INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l12','neighbor','neighbour','邻居;美语拼 neighbor,英式拼 neighbour') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
