INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l13','at present','',NULL,'/ət ˈprezənt/','At present, they are traveling across the country.','目前,他们正在全国巡演。','At present, I am living in New York.','目前,我住在纽约。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l13','as usual','',NULL,'/əz ˈjuːʒuəl/','As usual, the police will have a difficult time.','和往常一样,警察会很忙。','As usual, he was late.','和往常一样,他迟到了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l13','keep order','',NULL,'/kiːp ˈɔːrdər/','They will be trying to keep order.','他们将努力维持秩序。','The teachers keep order at the school gate.','老师们在校门口维持秩序。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp1','choice','{"stem":"将来进行时表示什么?","options":["到现在为止的经历","将来某个时候正在进行的事","此刻正在进行的事","过去发生的事"],"answer_index":1,"explanation_cn":"将来进行时表示\"将来某个时候正在做\"的事,比如明天这个时候正在干什么。✓ They will be arriving tomorrow."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp1','choice','{"stem":"将来进行时由什么构成?","options":["will/shall be + 动词-ing","have + 过去分词","be + 过去分词","will + 动词原形"],"answer_index":0,"explanation_cn":"将来进行时 = will/shall be + 动词-ing。✓ They will be singing tomorrow evening."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp1','choice','{"stem":"\"They ___ here tomorrow.\"(arrive,将来进行时)","options":["are arriving","will be arriving","will arrived","arrived"],"answer_index":1,"explanation_cn":"tomorrow(明天)+ \"将要到达\"用将来进行时 will be arriving。✓ They will be arriving here tomorrow."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp2','choice','{"stem":"\"现在他们正在踢球\"(此刻正在 → 现在进行):","options":["They played football.","They play football.","They are playing football.","They will be playing football."],"answer_index":2,"explanation_cn":"\"现在正在踢球\"用现在进行时 are playing。✓ They are playing football."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp2','choice','{"stem":"\"明天这个时候他们将在踢球\"(将来某时正在 → 将来进行):","options":["They will be playing football tomorrow.","They play football tomorrow.","They played football tomorrow.","They are playing football tomorrow."],"answer_index":0,"explanation_cn":"\"明天这个时候将在踢球\"用将来进行时 will be playing。✓ They will be playing football tomorrow."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp2','choice','{"stem":"\"He is working in the garden.\" 改成明天(将来进行时):","options":["He works in the garden tomorrow.","He worked in the garden tomorrow.","He will be working in the garden tomorrow.","He is working in the garden tomorrow."],"answer_index":2,"explanation_cn":"把现在进行(is working)改成明天,用将来进行时 will be working。✓ He will be working in the garden tomorrow."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp3','choice','{"stem":"\"我下周会见到你\"(将来进行,口语缩略):","options":["I''ll be seeing you next week.","I am be seeing you next week.","I''ll seeing you next week.","I be seeing you next week."],"answer_index":0,"explanation_cn":"将来进行时口语缩略:I will be → I''ll be,后接动词-ing seeing。✓ I''ll be seeing you next week."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp3','choice','{"stem":"\"他将乘火车来\"(将来进行,he):","options":["He''ll be come by train.","He''ll be coming by train.","He''ll being come by train.","He be coming by train."],"answer_index":1,"explanation_cn":"he will be 缩略成 he''ll be,后接动词-ing coming。✓ He''ll be coming by train."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp4','choice','{"stem":"\"明天这时候你会在洗车吗?\"(将来进行疑问):","options":["Will you be washing your car tomorrow?","Will you washing your car tomorrow?","Are you will be washing your car?","Do you be washing your car tomorrow?"],"answer_index":0,"explanation_cn":"将来进行时疑问:把 will 提到最前面(Will you be + 动词-ing…?)。✓ Will you be washing your car tomorrow?"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp4','choice','{"stem":"将来进行时的否定形式是:","options":["not will be + 动词-ing","won''t + 动词原形","don''t be + 动词-ing","won''t be + 动词-ing"],"answer_index":3,"explanation_cn":"将来进行时否定 = won''t(will not)be + 动词-ing。✓ I won''t be working tomorrow."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp5','choice','{"stem":"\"He''ll arrive in a minute.\" 换成将来进行时,意思不变:","options":["He''ll been arriving in a minute.","He''ll be arriving in a minute.","He is arrive in a minute.","He arriving in a minute."],"answer_index":1,"explanation_cn":"一般将来 He''ll arrive 换成将来进行 He''ll be arriving,意思一样,都表将来。✓"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp5','choice','{"stem":"关于将来进行时和一般将来时,正确的是:","options":["将来进行时表过去","一般将来时表此刻正在","两者常可互换,都表将来","两者意思完全相反"],"answer_index":2,"explanation_cn":"将来进行时和一般将来时常常可以互换使用,都表示将来的动作。✓ He''ll come = He''ll be coming."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp6','choice','{"stem":"\"They will be arriving here tomorrow.\" 这句将来进行时表示:","options":["已经安排好、最近就要发生的事","过去正在做的事","已经完成的事","经常反复的习惯"],"answer_index":0,"explanation_cn":"将来进行时常表示\"已经安排好、最近就要发生\"的事。✓ They will be arriving tomorrow.(快到了)"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp6','choice','{"stem":"\"明晚他们将在俱乐部演出\"(安排好的将来 → 将来进行):","options":["Tomorrow evening they sang at the club.","Tomorrow evening they are sung at the club.","Tomorrow evening they sing at the club yesterday.","Tomorrow evening they will be singing at the club."],"answer_index":3,"explanation_cn":"\"明晚将在俱乐部演出\"是安排好的将来,用将来进行时 will be singing。✓"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp7','choice','{"stem":"\"他们将乘火车来\"—— 乘坐交通工具用:","options":["in train","on train","by train","with train"],"answer_index":2,"explanation_cn":"乘坐交通工具用 by:by train(乘火车),名词前不加 the/a。✓ They will be coming by train."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp7','choice','{"stem":"\"坐飞机\"用英语说:","options":["on the air","with air","by airplane''s","by air"],"answer_index":3,"explanation_cn":"\"坐飞机\"用 by air。同类:by train / by sea / by bus。✓"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp8','choice','{"stem":"\"目前他们正在全国巡演\"(at present,此刻正在 → 现在进行):","options":["At present, they traveled.","At present, they are traveling.","At present, they will be traveling.","At present, they travel yesterday."],"answer_index":1,"explanation_cn":"at present(目前)表示此刻正在,用现在进行时 are traveling。✓ At present, they are traveling."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',5,'am2_l13_gp8','choice','{"stem":"at present 后面常配哪个时态?","options":["将来进行时","过去进行时","一般过去时","现在进行时(am/is/are + doing)"],"answer_index":3,"explanation_cn":"at present(目前/现在)常和现在进行时搭配,表示此刻正在做的事。✓"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',6,NULL,'choice','{"stem":"美语\"市中心\"常说:","options":["mid-town road","town centre","city inside","downtown"],"answer_index":3,"explanation_cn":"美语\"市中心\"常说 downtown;英式说 town centre。✓ singing downtown."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',6,NULL,'choice','{"stem":"美语\"排队\"常说:","options":["queue","row up","line up","stand line"],"answer_index":2,"explanation_cn":"美语\"排队\"常说 line up;英式说 queue。✓ Fans will be lining up."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',6,NULL,'choice','{"stem":"\"旅行\"进行时的美式拼写(单 l):","options":["traveleing","travling","travelling","traveling"],"answer_index":3,"explanation_cn":"美语里 travel 加 -ing 只用一个 l:traveling;英式用两个 l:travelling。✓"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',6,NULL,'choice','{"stem":"at present 的意思是:","options":["过去","将来","目前,现在","立刻"],"answer_index":2,"explanation_cn":"at present = 目前、现在。✓ At present, they are traveling."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',6,NULL,'choice','{"stem":"as usual 的意思是:","options":["像往常一样","偶尔","第一次","不同寻常地"],"answer_index":0,"explanation_cn":"as usual = 像往常一样、照例。✓ As usual, the police will be busy."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',6,NULL,'choice','{"stem":"keep order 的意思是:","options":["下命令","排顺序","维持秩序","点菜"],"answer_index":2,"explanation_cn":"keep order = 维持秩序。✓ They will be trying to keep order."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',7,NULL,'cloze','{"stem":"第 1 空","context":"The Silver Hawks ___1___ in our town tomorrow. They ___2___ by train, and the fans ___3___ them at the station. Tomorrow evening, they ___4___ at the club.","blank_no":1,"options":["will be arriving","arrived","are arriving now","arrive yesterday"],"answer_index":0,"explanation_cn":"tomorrow + 将来某时正在 → 将来进行时 will be arriving。✓ The Silver Hawks will be arriving tomorrow."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',7,NULL,'cloze','{"stem":"第 2 空","context":"The Silver Hawks ___1___ in our town tomorrow. They ___2___ by train, and the fans ___3___ them at the station. Tomorrow evening, they ___4___ at the club.","blank_no":2,"options":["will be coming","came","come yesterday","were coming"],"answer_index":0,"explanation_cn":"将来进行时 will be coming。✓ They will be coming by train."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',7,NULL,'cloze','{"stem":"第 3 空","context":"The Silver Hawks ___1___ in our town tomorrow. They ___2___ by train, and the fans ___3___ them at the station. Tomorrow evening, they ___4___ at the club.","blank_no":3,"options":["will be meeting","met","meet yesterday","were meeting"],"answer_index":0,"explanation_cn":"将来进行时 will be meeting。✓ The fans will be meeting them at the station."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',7,NULL,'cloze','{"stem":"第 4 空","context":"The Silver Hawks ___1___ in our town tomorrow. They ___2___ by train, and the fans ___3___ them at the station. Tomorrow evening, they ___4___ at the club.","blank_no":4,"options":["will be singing","sang","are singing now","sing yesterday"],"answer_index":0,"explanation_cn":"安排好的将来 → 将来进行时 will be singing。✓ Tomorrow evening, they will be singing at the club."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',8,NULL,'choice','{"stem":"When will the Silver Hawks arrive in town?","options":["Next week","Today","Next month","Tomorrow"],"answer_index":3,"explanation_cn":"课文说 They will be arriving in our town tomorrow,乐队明天到。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',8,NULL,'choice','{"stem":"How will they be coming?","options":["By plane","By bus","By train","By car"],"answer_index":2,"explanation_cn":"课文说 They will be coming by train,他们乘火车来。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',8,NULL,'choice','{"stem":"How long will the band stay?","options":["Five days","Two days","Ten days","One week"],"answer_index":0,"explanation_cn":"课文说 The Silver Hawks will be staying for five days,乐队待五天。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',9,NULL,'choice','{"stem":"你想说\"明天这个时候我将在飞机上\"(将来某时正在 → 将来进行):","options":["This time tomorrow I am flying now.","This time tomorrow I will be flying.","This time tomorrow I flew.","This time tomorrow I fly."],"answer_index":1,"explanation_cn":"\"明天这个时候将在飞机上\"是将来某时正在进行,用将来进行时 will be flying。✓ 场合:说自己明天的行程。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',9,NULL,'choice','{"stem":"你想问朋友\"今晚八点你会在做什么?\"(将来进行疑问):","options":["What do you doing at eight tonight?","What will you did at eight tonight?","What will you be doing at eight tonight?","What you will be doing at eight?"],"answer_index":2,"explanation_cn":"问\"今晚八点你会在做什么\",用将来进行时疑问 Will you be doing…?。✓ 场合:约朋友前先问对方安排。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',9,NULL,'choice','{"stem":"\"我一会儿就到\"—— 下面哪句用将来进行时,意思一样?","options":["I''ll be coming in a minute.","I am come in a minute.","I came in a minute.","I be coming in a minute."],"answer_index":0,"explanation_cn":"\"一会儿就到\"可用将来进行时 I''ll be coming,和一般将来 I''ll come 意思一样。✓"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',10,NULL,'choice','{"stem":"group 的意思是:","options":["城市","个人","团体,小组","老师"],"answer_index":2,"explanation_cn":"group = 团体、小组。✓ a group of pop singers."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',10,NULL,'choice','{"stem":"occasion 的意思是:","options":["习惯","假期","职业","场合"],"answer_index":3,"explanation_cn":"occasion = 场合。✓ on these big occasions."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',10,NULL,'choice','{"stem":"\"This time tomorrow, I ___ on the beach.\"(lie,将来进行)","options":["am lying now","lay","will be lying","lie"],"answer_index":2,"explanation_cn":"This time tomorrow(明天这个时候)+ 正在 → 将来进行时 will be lying。✓ I will be lying on the beach."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',10,NULL,'choice','{"stem":"\"他们明天将在俱乐部演出\"(将来进行):","options":["They are performing at the club yesterday.","They will be performing at the club tomorrow.","They perform at the club last night.","They performed at the club tomorrow."],"answer_index":1,"explanation_cn":"\"明天将在俱乐部演出\"是安排好的将来,用将来进行时 will be performing。✓"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',10,NULL,'choice','{"stem":"\"Will you be using the car tomorrow?\" 这句话在问:","options":["你会修车吗","你昨天用车了吗","你明天会用车吗","你现在正在用车吗"],"answer_index":2,"explanation_cn":"Will you be using the car tomorrow? 用将来进行时,问\"你明天会用车吗\"(常用来礼貌地打听安排)。✓"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',10,NULL,'choice','{"stem":"\"坐公交车\"用英语说:","options":["by bus","in bus","with the bus","on a bus''s"],"answer_index":0,"explanation_cn":"\"坐公交车\"用 by bus,名词前不加 the/a。✓"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',10,NULL,'choice','{"stem":"How will the fans welcome the Silver Hawks?","options":["They will send letters","They will stay home","They will call the band","They will be meeting the band at the station"],"answer_index":3,"passage":"The Silver Hawks are a group of pop singers. At present, they are traveling all across the country. They will be arriving in our town tomorrow. They will be coming by train, and most of the young fans will be meeting them at the station. Tomorrow evening, they will be singing downtown at the Community Club. The Silver Hawks will be staying for five days, and they will give five performances. Hundreds of fans will be lining up outside the club for hours. As usual, the police will have a difficult time. They will be trying hard to keep order. It is always the same on these big occasions. What will you be doing when the Silver Hawks arrive?","explanation_cn":"课文说 most of the young fans will be meeting them at the station,粉丝会去车站接。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',10,NULL,'choice','{"stem":"Why will the police be busy?","options":["They will be trying to keep order among the crowds","They will be closing the roads all day","They will be selling tickets","They will be singing with the band"],"answer_index":0,"passage":"The Silver Hawks are a group of pop singers. At present, they are traveling all across the country. They will be arriving in our town tomorrow. They will be coming by train, and most of the young fans will be meeting them at the station. Tomorrow evening, they will be singing downtown at the Community Club. The Silver Hawks will be staying for five days, and they will give five performances. Hundreds of fans will be lining up outside the club for hours. As usual, the police will have a difficult time. They will be trying hard to keep order. It is always the same on these big occasions. What will you be doing when the Silver Hawks arrive?","explanation_cn":"课文说 the police will be trying to keep order,人多,警察忙着维持秩序。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',10,NULL,'choice','{"stem":"Where will the band perform?","options":["At the harbor","At the train station","At the Community Club downtown","At a school"],"answer_index":2,"audio":"The Silver Hawks are a group of pop singers. At present, they are traveling all across the country. They will be arriving in our town tomorrow. They will be coming by train, and most of the young fans will be meeting them at the station. Tomorrow evening, they will be singing downtown at the Community Club. The Silver Hawks will be staying for five days, and they will give five performances. Hundreds of fans will be lining up outside the club for hours. As usual, the police will have a difficult time. They will be trying hard to keep order. It is always the same on these big occasions. What will you be doing when the Silver Hawks arrive?","explanation_cn":"课文说 they will be singing downtown at the Community Club,在市中心的社区俱乐部演出。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l13',10,NULL,'choice','{"stem":"What are the Silver Hawks doing at present?","options":["Making a movie","Recording an album","Resting at home","Traveling across the country"],"answer_index":3,"audio":"The Silver Hawks are a group of pop singers. At present, they are traveling all across the country. They will be arriving in our town tomorrow. They will be coming by train, and most of the young fans will be meeting them at the station. Tomorrow evening, they will be singing downtown at the Community Club. The Silver Hawks will be staying for five days, and they will give five performances. Hundreds of fans will be lining up outside the club for hours. As usual, the police will have a difficult time. They will be trying hard to keep order. It is always the same on these big occasions. What will you be doing when the Silver Hawks arrive?","explanation_cn":"课文说 At present, they are traveling all across the country,目前他们正在全国巡演。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l14',2,2,14,'Do you speak English?','你会讲英语吗?','过去完成时(主考:had+过去分词 · after/before/as soon as/when/until 引导 · 两个过去动作里更早的用过去完成 · 否定 had not · 一般过去 vs 过去完成辨析)+ had planned/hoped 未实现的计划(辅考讲深)+ It was the…time that…had done(辅考讲深)','去年在法国旅行搭载招手青年 · 全程用法语没说话 · 快到镇上时青年突然慢慢问"你会讲英语吗"——原来他也是英国人','{"q":"Listen and answer — Did the young man speak English?","options":["Yes — he was English himself","No, only French","No, he was silent the whole time","Yes, but very badly"],"answer_index":0}'::jsonb,'{"title":"说\"在另一件过去的事之前已经做了\"(过去完成时)","intro":"本课讲怎么说\"过去的两件事里,哪一件先发生\"——先发生的那件用过去完成时。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["过去完成时 = had + 过去分词(表示''过去的过去'')","After I had left the village, I drove on.(先离开,后开车)"],["两个过去动作里,先发生的用过去完成,后发生的用一般过去","As soon as he had gotten in, I said good morning.(先上车,后问好)"],["常配 after / before / as soon as / when 连词","When he had finished lunch, he asked for water."],["否定:had not + 过去分词;常和 until 连用","I had not understood the problem until he explained it."]]},"specialRules":[{"rule":"相继发生、按顺序讲的动作,用一般过去时(and/but 连接);过去完成时是''回头看''更早发生的那件事","mark":"过去 vs 过去完成"},{"rule":"had planned/hoped/intended to + 原形,表示''本打算…(但没实现)''","mark":"未实现的计划"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l14',1,NULL,'I had an amusing experience last summer while I was on vacation in France.','去年夏天我在法国度假时,有过一次有趣的经历。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l14',2,NULL,'After I had left a small village in the south of France, I drove on toward the next town.','离开法国南部的一个小村庄后,我继续驶向下一个城镇。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l14',3,NULL,'On the way, a young man waved at me and asked me for a lift.','途中,一个青年向我招手,请求搭个便车。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l14',4,NULL,'As soon as he had gotten into the car, I said good morning to him in French.','他一上车,我就用法语跟他道了早安。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l14',5,NULL,'He replied in the same language, so I figured he was a local Frenchman.','他也用法语回答我,于是我以为他是本地的法国人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l14',6,NULL,'Apart from a few words, I did not know any French at all.','除了几个单词,我根本不会法语。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l14',7,NULL,'Neither of us spoke during the whole journey.','一路上我们俩谁也没说话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l14',8,NULL,'I had nearly reached the town when the young man suddenly turned to me.','我快到镇上时,那青年突然转向我。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l14',9,NULL,'Very slowly, he asked, "Do you speak English?"','他慢慢地问道:"你会讲英语吗?"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l14',10,NULL,'I was surprised, because before he spoke, I had thought he was French.','我很吃惊,因为在他开口之前,我一直以为他是法国人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l14',11,NULL,'As I soon learned, the young man was English himself!','我很快就知道,这青年自己就是个英国人!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
