INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l14','on the way','',NULL,'/ɑːn ðə weɪ/','On the way, a young man waved at me.','途中,一个青年向我招手。','I bought some coffee on the way to work.','上班途中我买了点咖啡。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l14','ask for a lift','',NULL,'/æsk fər ə lɪft/','He asked me for a lift.','他请求搭我的便车。','She asked her neighbor for a lift to the airport.','她请邻居捎她去机场。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l14','apart from','',NULL,'/əˈpɑːrt frəm/','Apart from a few words, I did not know any French.','除了几个单词,我根本不会法语。','Apart from Tom, everyone came.','除了汤姆,大家都来了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp1','choice','{"stem":"过去完成时由什么构成?","options":["was + 过去分词","had + 过去分词","will + 动词原形","have + 过去分词"],"answer_index":1,"explanation_cn":"过去完成时 = had + 过去分词,表示\"过去的过去\"(比某个过去时间更早发生)。✓ After I had left the village…"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp1','choice','{"stem":"\"After I ___ the village, I drove on.\"(leave,先离开 → 过去完成)","options":["had left","was leaving","left","have left"],"answer_index":0,"explanation_cn":"\"离开村庄\"发生在\"开车走\"之前,先发生的用过去完成时 had left。✓ After I had left the village, I drove on."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp1','choice','{"stem":"\"When he ___ lunch, he asked for water.\"(finish,先吃完 → 过去完成)","options":["finished","has finished","finishes","had finished"],"answer_index":3,"explanation_cn":"\"吃完午饭\"在\"要水\"之前,先发生的用过去完成时 had finished。✓ When he had finished lunch, he asked for water."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp2','choice','{"stem":"过去完成时用来表示什么?","options":["将来要做的事","过去两个动作里,先发生的那个","此刻正在做的事","经常反复的习惯"],"answer_index":1,"explanation_cn":"过去完成时用来表示过去的两个动作里,哪一个更早发生(先发生的用过去完成)。✓"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp2','choice','{"stem":"\"As soon as he had gotten into the car, I said hi.\" 哪件事先发生?","options":["他上车(had gotten in)","我打招呼(said hi)","都没发生","两件同时"],"answer_index":0,"explanation_cn":"had gotten in 是过去完成时,表示更早发生;said hi 是一般过去时,后发生。所以先发生的是\"上车\"。✓"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp3','choice','{"stem":"\"The children ran away ___ they had broken the window.\"(在…之后)","options":["and","after","so","before"],"answer_index":1,"explanation_cn":"\"孩子们打碎玻璃之后跑了\"——\"在…之后\"用 after,后接过去完成时 had broken。✓ ran away after they had broken the window."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp3','choice','{"stem":"\"___ the sun had set, we returned to the hotel.\"(太阳一下山就…)","options":["Because","Although","Unless","As soon as"],"answer_index":3,"explanation_cn":"\"太阳一下山我们就回旅馆\"——\"一…就…\"用 As soon as,后接过去完成时 had set。✓ As soon as the sun had set, we returned."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp3','choice','{"stem":"\"She went to the post office ___ she had written the letter.\"(先写完信)","options":["until","but","after","or"],"answer_index":2,"explanation_cn":"\"写完信之后去邮局\"——先写完(had written)后去,用 after 引导。✓ She went to the post office after she had written the letter."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp4','choice','{"stem":"\"I ___ the problem until he explained it.\"(否定 + until,过去完成)","options":["did not understand","was not understanding","have not understood","had not understood"],"answer_index":3,"explanation_cn":"过去完成时否定 = had not + 过去分词,常和 until 连用(直到…才…)。✓ I had not understood the problem until he explained it."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp5','choice','{"stem":"关于一般过去时和过去完成时,正确的是:","options":["过去完成时表将来","一般过去时表此刻正在","相继发生按顺序讲用一般过去;回头看更早的用过去完成","两个时态完全一样"],"answer_index":2,"explanation_cn":"两件相继发生、按先后顺序讲的事,用一般过去时;过去完成时是\"回头看\"更早发生的那件。✓"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp5','choice','{"stem":"\"He arrived and (then) sat down.\" 两件相继发生、按顺序讲,用:","options":["过去完成(had arrived, had sat)","一般过去(arrived, sat)","现在完成","将来时"],"answer_index":1,"explanation_cn":"\"到了然后坐下\"是相继发生、按顺序讲的两件事,都用一般过去时 arrived, sat,不用过去完成时。✓"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp5','choice','{"stem":"\"When I got to the station, the train ___ already ___.\"(我到之前车已开走 → 过去完成)","options":["was … leaving","did … leave","had … left","has … left"],"answer_index":2,"explanation_cn":"\"我到车站之前,火车已经开走了\"——开走在\"到\"之前,用过去完成时 had already left。✓ When I got to the station, the train had already left."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp6','choice','{"stem":"\"I ___ to go shopping, but my mom came.\"(本打算…但没成 → had planned)","options":["had planned","will plan","plan","am planning"],"answer_index":0,"explanation_cn":"\"本打算去购物,但妈妈来了(没去成)\"——本打算而未实现,用 had planned to。✓ I had planned to go shopping, but my mom came."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp6','choice','{"stem":"\"She ___ that he would come, but he didn''t.\"(原本希望…但落空 → had hoped)","options":["is hoping","hopes","will hope","had hoped"],"answer_index":3,"explanation_cn":"\"原本希望他来,但他没来\"——原本希望而落空,用 had hoped that。✓ She had hoped that he would come, but he didn''t."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp7','choice','{"stem":"\"It was the third time that I ___ him.\"(在…句式里用过去完成)","options":["met","have met","had met","meet"],"answer_index":2,"explanation_cn":"\"这是我第三次见他\"用 \"It was the … time that + 过去完成时\" 句式,填 had met。✓ It was the third time that I had met him."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp8','choice','{"stem":"过去完成时的否定是:","options":["did not + 过去分词","have not + 过去分词","was not + 过去分词","had not + 过去分词"],"answer_index":3,"explanation_cn":"过去完成时的否定 = had not + 过去分词。✓ I had not seen him before."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp8','choice','{"stem":"\"___ you ever seen him before that day?\"(过去完成疑问)","options":["Did","Had","Have","Were"],"answer_index":1,"explanation_cn":"过去完成时的疑问,把 had 提到句子最前面。✓ Had you ever seen him before that day?"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp8','choice','{"stem":"\"By six o''clock, they ___ dinner.\"(到六点之前已吃完 → 过去完成)","options":["finish","have finished","had finished","finished"],"answer_index":2,"explanation_cn":"\"到六点之前他们已吃完饭\"——吃完在\"六点\"之前,用过去完成时 had finished。✓ By six o''clock, they had finished dinner."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"美语里\"搭便车\"更常说:","options":["ride","car help","lift","hitch stop"],"answer_index":0,"explanation_cn":"美语里\"搭便车\"更常说 ride(give sb a ride);英式说 lift。✓ Can you give me a ride?"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"美语里\"旅程/旅行\"更常说:","options":["voyage road","way go","journey","trip"],"answer_index":3,"explanation_cn":"美语里\"旅程/旅行\"更常说 trip;英式常说 journey。✓ a road trip."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"美语里\"假期\"用:","options":["vacation","holiday","offtime","restday"],"answer_index":0,"explanation_cn":"美语\"假期\"用 vacation;英式用 holiday。✓ on vacation in France."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"on the way 的意思是:","options":["迷路了","在起点","在路边","在途中"],"answer_index":3,"explanation_cn":"on the way = 在途中、在路上。✓ On the way, a young man waved."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"ask for a lift 的意思是:","options":["请求帮忙提东西","要一杯水","要求搭便车","问路"],"answer_index":2,"explanation_cn":"ask for a lift = 要求搭便车。✓ He asked me for a lift."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"apart from 的意思是:","options":["紧挨着","除了…以外","关于","属于"],"answer_index":1,"explanation_cn":"apart from = 除了…以外。✓ Apart from a few words, I did not know any French."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',7,NULL,'cloze','{"stem":"第 1 空","context":"After I ___1___ the village, I ___2___ on toward the next town. A young man asked me for a lift. As soon as he ___3___ into the car, I said hi in French. I ___4___ nearly reached the town when he asked, \"Do you speak English?\"","blank_no":1,"options":["had left","leave","have left","was leaving"],"answer_index":0,"explanation_cn":"\"离开村庄\"先发生,用过去完成时 had left。✓ After I had left the village…"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',7,NULL,'cloze','{"stem":"第 2 空","context":"After I ___1___ the village, I ___2___ on toward the next town. A young man asked me for a lift. As soon as he ___3___ into the car, I said hi in French. I ___4___ nearly reached the town when he asked, \"Do you speak English?\"","blank_no":2,"options":["drove","had driven","drive","was driven"],"answer_index":0,"explanation_cn":"\"继续开车\"后发生,用一般过去时 drove。✓ I drove on toward the next town."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',7,NULL,'cloze','{"stem":"第 3 空","context":"After I ___1___ the village, I ___2___ on toward the next town. A young man asked me for a lift. As soon as he ___3___ into the car, I said hi in French. I ___4___ nearly reached the town when he asked, \"Do you speak English?\"","blank_no":3,"options":["had gotten","got","has gotten","gets"],"answer_index":0,"explanation_cn":"\"上车\"先于\"打招呼\",用过去完成时 had gotten。✓ As soon as he had gotten into the car…"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',7,NULL,'cloze','{"stem":"第 4 空","context":"After I ___1___ the village, I ___2___ on toward the next town. A young man asked me for a lift. As soon as he ___3___ into the car, I said hi in French. I ___4___ nearly reached the town when he asked, \"Do you speak English?\"","blank_no":4,"options":["had","have","was","did"],"answer_index":0,"explanation_cn":"\"快到镇上\"是更早的背景,用过去完成时 had reached。✓ I had nearly reached the town when…"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',8,NULL,'choice','{"stem":"Where did the writer pick up the young man?","options":["On the way to the next town","In the town center","At a gas station","At the airport"],"answer_index":0,"explanation_cn":"课文说 On the way, a young man waved at me,作者在去下个镇的途中搭上他。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',8,NULL,'choice','{"stem":"Did they talk during the journey?","options":["Yes, they talked a lot","No, neither of them spoke","Only the driver spoke","Yes, in English"],"answer_index":1,"explanation_cn":"课文说 Neither of us spoke during the whole journey,一路上谁也没说话。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',8,NULL,'choice','{"stem":"What nationality was the young man?","options":["German","French","American","English"],"answer_index":3,"explanation_cn":"课文结尾说 the young man was English himself,那青年其实是英国人。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',9,NULL,'choice','{"stem":"你想说\"我到车站时,火车已经开走了\"(到之前已开走 → 过去完成):","options":["When I got to the station, the train had already left.","When I got to the station, the train leaves.","When I got to the station, the train was leaving now.","When I got to the station, the train has left."],"answer_index":0,"explanation_cn":"\"火车开走\"在\"我到\"之前,先发生的用过去完成时 had already left。✓ 场合:解释自己为什么没赶上车。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',9,NULL,'choice','{"stem":"你想说\"她写完作业后就睡了\"(先写完 → after…had done):","options":["After she has finished her homework, she went to bed.","After she will finish her homework, she went to bed.","After she had finished her homework, she went to bed.","After she finishes her homework, she went to bed."],"answer_index":2,"explanation_cn":"\"写完作业\"先发生,用 after + 过去完成时 had finished;\"睡觉\"后发生用一般过去 went。✓"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',9,NULL,'choice','{"stem":"你想说\"我本打算去看你,但太忙了\"(本打算但没成 → had planned):","options":["I have planned to visit you, but I was too busy.","I will plan to visit you, but I was too busy.","I plan to visit you, but I was too busy.","I had planned to visit you, but I was too busy."],"answer_index":3,"explanation_cn":"\"本打算去看你但没成\"用 had planned to,表示过去未实现的计划。✓ 场合:向朋友解释爽约。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"amusing 的意思是:","options":["有趣的,好笑的","危险的","重要的","无聊的"],"answer_index":0,"explanation_cn":"amusing = 有趣的、好笑的。✓ an amusing experience."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"journey 的意思是:","options":["工作","语言","旅程,旅行","村庄"],"answer_index":2,"explanation_cn":"journey = 旅程、旅行。✓ during the whole journey."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"\"He told me that he ___ the book before.\"(read,更早读过 → 过去完成)","options":["will read","has read","reads","had read"],"answer_index":3,"explanation_cn":"\"他更早读过这本书\"(在告诉我之前),用过去完成时 had read。✓ He told me that he had read the book before."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"\"By the time we arrived, the movie ___.\"(我们到之前已开始 → 过去完成)","options":["had started","was starting now","has started","starts"],"answer_index":0,"explanation_cn":"\"我们到之前电影已经开始\"——开始在\"到\"之前,用过去完成时 had started。✓ By the time we arrived, the movie had started."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"\"After he had eaten, he washed the dishes.\" 哪件事先发生?","options":["都没发生","他吃饭(had eaten)","两件同时","他洗碗(washed)"],"answer_index":1,"explanation_cn":"had eaten 是过去完成时,更早发生;washed 是一般过去时,后发生。所以先发生的是\"吃饭\"。✓"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"\"我本想给你打电话,可手机没电了\"(本打算但没成)用:","options":["am calling","will call","plan to call","had planned to call"],"answer_index":3,"explanation_cn":"\"本想打电话,可手机没电了(没打成)\"用 had planned to call,表示过去未实现的打算。✓"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"Why did the writer speak French to the young man?","options":["He thought the young man was a local Frenchman","It was the law in France","He wanted to practice French","The young man asked him to"],"answer_index":0,"passage":"I had an amusing experience last summer while I was on vacation in France. After I had left a small village in the south of France, I drove on toward the next town. On the way, a young man waved at me and asked me for a lift. As soon as he had gotten into the car, I said good morning to him in French. He replied in the same language, so I figured he was a local Frenchman. Apart from a few words, I did not know any French at all. Neither of us spoke during the whole journey. I had nearly reached the town when the young man suddenly turned to me. Very slowly, he asked, \"Do you speak English?\" I was surprised, because before he spoke, I had thought he was French. As I soon learned, the young man was English himself!","explanation_cn":"课文说作者以为那青年是本地法国人,所以用法语跟他说话。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"What surprised the writer at the end?","options":["The town was closed","The young man could not speak","The car broke down","The young man was actually English"],"answer_index":3,"passage":"I had an amusing experience last summer while I was on vacation in France. After I had left a small village in the south of France, I drove on toward the next town. On the way, a young man waved at me and asked me for a lift. As soon as he had gotten into the car, I said good morning to him in French. He replied in the same language, so I figured he was a local Frenchman. Apart from a few words, I did not know any French at all. Neither of us spoke during the whole journey. I had nearly reached the town when the young man suddenly turned to me. Very slowly, he asked, \"Do you speak English?\" I was surprised, because before he spoke, I had thought he was French. As I soon learned, the young man was English himself!","explanation_cn":"课文结尾揭示那青年其实是英国人,这让作者很吃惊。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"How did the young man get the writer''s attention?","options":["He called his phone","He shouted from a window","He waved at him on the way","He blocked the road"],"answer_index":2,"audio":"I had an amusing experience last summer while I was on vacation in France. After I had left a small village in the south of France, I drove on toward the next town. On the way, a young man waved at me and asked me for a lift. As soon as he had gotten into the car, I said good morning to him in French. He replied in the same language, so I figured he was a local Frenchman. Apart from a few words, I did not know any French at all. Neither of us spoke during the whole journey. I had nearly reached the town when the young man suddenly turned to me. Very slowly, he asked, \"Do you speak English?\" I was surprised, because before he spoke, I had thought he was French. As I soon learned, the young man was English himself!","explanation_cn":"课文说 On the way, a young man waved at me,青年在途中招手拦车。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"When did the young man ask \"Do you speak English?\"","options":["Before the trip started","Right when he got in the car","At the gas station","Near the end, close to the town"],"answer_index":3,"audio":"I had an amusing experience last summer while I was on vacation in France. After I had left a small village in the south of France, I drove on toward the next town. On the way, a young man waved at me and asked me for a lift. As soon as he had gotten into the car, I said good morning to him in French. He replied in the same language, so I figured he was a local Frenchman. Apart from a few words, I did not know any French at all. Neither of us spoke during the whole journey. I had nearly reached the town when the young man suddenly turned to me. Very slowly, he asked, \"Do you speak English?\" I was surprised, because before he spoke, I had thought he was French. As I soon learned, the young man was English himself!","explanation_cn":"课文说 I had nearly reached the town when the young man suddenly asked,快到镇上时他才问。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
